{
  "sql": "WITH returned_units AS (SELECT r.product_id, SUM(r.return_quantity) AS returned_units FROM commerce.returns AS r JOIN commerce.orders AS o ON r.order_id = o.order_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY r.product_id), ordered_units AS (SELECT oi.product_id, SUM(oi.quantity) AS ordered_units FROM commerce.order_items AS oi JOIN commerce.orders AS o ON oi.order_id = o.order_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY oi.product_id) SELECT p.product_id, p.product_name, ru.returned_units, ou.ordered_units, CAST(ru.returned_units AS NUMERIC) / NULLIF(ou.ordered_units, 0) AS return_ratio FROM returned_units AS ru INNER JOIN ordered_units AS ou ON ru.product_id = ou.product_id JOIN commerce.products AS p ON ru.product_id = p.product_id ORDER BY 5 DESC NULLS LAST, 1 ASC LIMIT 200",
  "parameters": [
    "2022-01-01",
    "2023-01-01"
  ],
  "explanation": "Calculates the ratio of returned units to ordered units for each product in 2022. It independently aggregates return quantities and order item quantities by product, joins them on product_id, and ranks by the resulting ratio in descending order."
}

